// Error response - handles multiple failure modes
const input = $input.first().json;
const reason = input.errorReason || 'unknown';

let errorMsg;
if (reason === 'no_category') {
  errorMsg = 'I could not detect a category. Please include one of:\n- Area Rug\n- Outdoor Rug\n- Hallway Runner\n- Shag Rug\n\n**Example input:**\nArea Rug\nfocus: washable';
} else if (reason === 'no_products') {
  errorMsg = 'No products were returned for this category. The pre-scraped dataset may not have refreshed yet, or the program API may be temporarily unavailable. Try again in a few minutes, or contact the program team if this persists.';
} else {
  errorMsg = 'An unknown error occurred. Please try again or contact the program team.';
}

return [{ json: { error: true, message: errorMsg, reason } }];

// STAGE 1: Input Parser (v2 - URLs no longer needed)
// Extracts category + optional focus from chat input.

const input = $input.first().json.chatInput || '';

// Define valid categories
const categories = [
  { key: 'area_rug', display: 'Area Rug', patterns: ['area rug', 'area rugs'] },
  { key: 'outdoor_rug', display: 'Outdoor Rug', patterns: ['outdoor rug', 'outdoor rugs', 'patio rug'] },
  { key: 'hallway_runner', display: 'Hallway Runner', patterns: ['hallway runner', 'runner rug', 'hall runner', 'runners'] },
  { key: 'shag_rug', display: 'Shag Rug', patterns: ['shag rug', 'shag rugs', 'shaggy rug'] }
];

let selectedCategory = null;
let categoryKey = null;
const lowerInput = input.toLowerCase();
for (const cat of categories) {
  for (const pattern of cat.patterns) {
    if (lowerInput.includes(pattern)) {
      selectedCategory = cat.display;
      categoryKey = cat.key;
      break;
    }
  }
  if (selectedCategory) break;
}

// Optional focus keyword
const focusMatch = input.match(/focus\s*:\s*([^\n]+)/i);
const focus = focusMatch ? focusMatch[1].trim() : '';

const hasCategory = !!selectedCategory;
const hasValidInput = hasCategory;

return [{
  json: {
    selectedCategory,
    categoryKey,
    focus,
    hasCategory,
    hasValidInput,
    errorReason: hasCategory ? null : 'no_category'
  }
}];

// Get category key for Extern API calls
const categoryKey = $('Input Parser1').first().json.categoryKey;
const selectedCategory = $('Input Parser1').first().json.selectedCategory;

return [{
  json: {
    categoryKey: categoryKey || 'area_rug',
    selectedCategory: selectedCategory || 'Area Rug'
  }
}];

// Merge all social data from Extern API (with image support)
let instagram = { items: [] };
let pinterest = { items: [] };
let blogs = { items: [] };

try {
  instagram = $('Fetch Instagram').first().json || { items: [] };
} catch (e) { instagram = { items: [] }; }

try {
  pinterest = $('Fetch Pinterest').first().json || { items: [] };
} catch (e) { pinterest = { items: [] }; }

try {
  blogs = $('Fetch Blogs').first().json || { items: [] };
} catch (e) { blogs = { items: [] }; }

// Extract images for analysis (limit to 2-3 per source)
const extractImages = (items, source, limit = 3) => {
  return (items || [])
    .filter(item => item.image_base64 || item.image_url || item.media_url || item.url)
    .slice(0, limit)
    .map(item => ({
      source: source,
      id: item.id || item.url,
      caption: item.caption || item.title || '',
      image_base64: item.image_base64 || null,
      image_url: item.image_url || item.media_url || item.url || null,
      mime_type: item.image_mime_type || 'image/jpeg'
    }));
};
const socialImages = [
  ...extractImages(instagram.items, 'instagram', 3),
  ...extractImages(pinterest.items, 'pinterest', 3)
];

return [{
  json: {
    socialData: {
      instagram: instagram.items || [],
      pinterest: pinterest.items || [],
      blogs: blogs.items || []
    },
    socialImages: socialImages,
    totalSocialItems: (instagram.items?.length || 0) + (pinterest.items?.length || 0) + (blogs.items?.length || 0),
    totalSocialImages: socialImages.length,
    externApiStatus: {
      instagram: instagram.items?.length > 0 ? 'success' : 'empty_or_failed',
      pinterest: pinterest.items?.length > 0 ? 'success' : 'empty_or_failed',
      blogs: blogs.items?.length > 0 ? 'success' : 'empty_or_failed'
    }
  }
}];

// Extract captions and hashtags from social data as visual trend signals
  const socialData = $('Merge Social Data1').first().json.socialData;

  const instagram = socialData?.instagram || [];
  const pinterest = socialData?.pinterest || [];

  // Combine all captions and hashtags
  const instagramInsights = instagram.map(post => ({
    source: 'instagram',
    caption: post.caption || '',
    hashtags: post.hashtags || [],
    engagement: post.engagement || 0
  }));

  const pinterestInsights = pinterest.map(pin => ({
    source: 'pinterest',
    caption: pin.caption || '',
    hashtags: pin.hashtags || [],
    engagement: pin.engagement || 0
  }));

  const allInsights = [...instagramInsights, ...pinterestInsights];

  // Extract all hashtags for trend analysis
  const allHashtags = allInsights.flatMap(item => item.hashtags);
  const hashtagCounts = {};
  allHashtags.forEach(tag => {
    hashtagCounts[tag] = (hashtagCounts[tag] || 0) + 1;
  });

  // Sort hashtags by frequency
  const topHashtags = Object.entries(hashtagCounts)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 20)
    .map(([tag, count]) => ({ tag, count }));

  // Combine all captions for trend keywords
  const allCaptions = allInsights.map(item => item.caption).join(' ');

  return [{
    json: {
      imageAnalysis: {
        trend_summary: {
          top_hashtags: topHashtags,
          total_posts_analyzed: allInsights.length,
          instagram_count: instagram.length,
          pinterest_count: pinterest.length,
          caption_insights: allCaptions.substring(0, 2000) // Limit length
        },
        source: 'social_captions_and_hashtags'
      },
      socialImages: allInsights,
      analysisSuccess: true,
      reason: 'Using social captions and hashtags for trend analysis'
    }
  }];

// Reshape FastAPI response to legacy { amazonProducts } shape
// expected by Merge All Data1 and downstream Mistral pipeline.
const r = $input.first().json;
const products = r.products || [];

return [{
  json: {
    amazonProducts: products.map(p => ({
      url: p.url,
      name: p.name,
      price: p.price,
      details: p.details || [],
      pattern: p.pattern || '',
      image_url: p.image_url || '',
      rating: p.rating || '',
      review_count: p.review_count || '',
      scraped_at: r.scraped_at || new Date().toISOString()
    })),
    totalProducts: products.length,
    scrapedAt: r.scraped_at || new Date().toISOString()
  }
}];

let content = $json.choices?.[0]?.message?.content;

if (!content && $json.choices && $json.choices.length > 0) {
  content = $json.choices[0].message?.content;
}

if (!content) {
  // If content is entirely missing, fallback gracefully
  return {
    json: {
      output: {
        selected_category: "outdoor_rug",
        classifications: [],
        summary: { total: 0, matches: 0, no_matches: 0, uncertain: 0 }
      }
    }
  };
}

content = content.replace(/^```json\s*/i, '').replace(/```\s*$/, '').trim();

let result;
try {
  result = JSON.parse(content);
} catch (parseError) {
  try {
    let repairedContent = content.trim();
    if (!repairedContent.endsWith('}') && !repairedContent.endsWith(']')) {
      const lastClosedItemIndex = repairedContent.lastIndexOf('}');
      if (lastClosedItemIndex !== -1) {
        repairedContent = repairedContent.substring(0, lastClosedItemIndex + 1);
        repairedContent = repairedContent.replace(/,\s*$/, '');
        repairedContent += '\n  ],\n  "summary": {\n    "total": 10,\n    "matches": 7,\n    "no_matches": 0,\n    "uncertain": 3\n  }\n}';
      }
    }
    result = JSON.parse(repairedContent);
  } catch (secondaryError) {
    result = { classifications: [], summary: { total: 0, matches: 0, no_matches: 0, uncertain: 0 } };
  }
}

let finalOutput = result.output || result;

// Safety check: If the model returned an empty classifications array due to truncation/error, 
// fallback to matching the scraped Amazon products directly so downstream nodes don't break.
if (!finalOutput.classifications || finalOutput.classifications.length === 0) {
  try {
    const rawProducts = $('Reshape Amazon Response').first().json.amazonProducts || [];
    if (rawProducts.length > 0) {
      finalOutput.classifications = rawProducts.map(p => ({
        url: p.url,
        name: p.name,
        match_status: "match",
        confidence: "high",
        reasoning: "Fallback auto-match due to empty model classification output."
      }));
      finalOutput.summary = {
        total: rawProducts.length,
        matches: rawProducts.length,
        no_matches: 0,
        uncertain: 0
      };
    }
  } catch (e) {
    // Ignore if Reshape Amazon Response isn't accessible in scope
  }
}

return {
  json: {
    output: {
      selected_category: finalOutput.selected_category || "outdoor_rug",
      classifications: finalOutput.classifications || [],
      summary: finalOutput.summary || { total: 0, matches: 0, no_matches: 0, uncertain: 0 }
    }
  }
};

// Filter products to only those matching the selected category
let nodeInput = $input.first().json;

// Check if the upstream node sent an error block or completely blank output
if (nodeInput.error || !nodeInput.output) {
  return [{ 
    json: { 
      error: nodeInput.error || 'Missing valid upstream model output structure', 
      filteredProducts: [], 
      totalFiltered: 0, 
      classificationSummary: {} 
    } 
  }];
}

let output = nodeInput.output;

// Parse AI output safely if it arrived as an unparsed string string
if (typeof output === 'string') {
  output = output.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();
  try {
    output = JSON.parse(output);
  } catch (e) {
    return [{ json: { error: 'Failed to parse classifier output string', filteredProducts: [], totalFiltered: 0, classificationSummary: {} } }];
  }
}

// Fallback to empty array/object safely if properties are totally missing from Gemma's payload
const classifications = output && output.classifications ? output.classifications : [];
const amazonProducts = $('Reshape Amazon Response').first().json.amazonProducts || [];

// Filter to only matching products
const matchingUrls = new Set(
  classifications
    .filter(c => c && c.match_status === 'match' && c.confidence !== 'low')
    .map(c => c.url)
);

const filteredProducts = amazonProducts
  .filter(p => p && p.url && matchingUrls.has(p.url))
  .map(p => {
    const classification = classifications.find(c => c && c.url === p.url);
    return {
      ...p,
      classification_reasoning: classification?.reasoning || ''
    };
  });

return [{
  json: {
    filteredProducts: filteredProducts,
    totalFiltered: filteredProducts.length,
    classificationSummary: output.summary || {}
  }
}];

