// Check the raw response content coming directly from the Standardize Details HTTP node
let content = $json.choices?.[0]?.message?.content;

// Fallback checking for alternative local engine return layouts
if (!content && $json.choices && $json.choices.length > 0) {
  content = $json.choices[0].message?.content;
}

if (!content) {
  throw new Error("The preceding Standardize Details node did not return a valid message text string body block.");
}

// Strip out any markdown wraps if Gemma wraps the payload natively
content = content.replace(/^```json\s*/i, '').replace(/```\s*$/, '').trim();

// Self-heal logic: Drop any conversational trailing apologies or text
if (content.includes('}') && !content.endsWith('}') && !content.endsWith(']')) {
  const lastBraceIndex = content.lastIndexOf('}');
  if (lastBraceIndex !== -1) {
    content = content.substring(0, lastBraceIndex + 1);
  }
}

// Handle severe mid-sentence clipping if the model ran out of tokens
if (content.endsWith('}') && !content.endsWith(']}') && !content.includes('"summary"')) {
  const lastClosedItemIndex = content.lastIndexOf('}');
  if (lastClosedItemIndex !== -1) {
    content = content.substring(0, lastClosedItemIndex + 1).replace(/,\s*$/, '');
    content += '\n  ],\n  "summary": {\n    "top_sizes": [],\n    "top_colors": [],\n    "price_distribution": {}\n  }\n}';
  }
}

let output;
try {
  output = JSON.parse(content);
} catch (parseError) {
  try {
    // Clean minor syntax errors like trailing stray array commas
    let cleanedContent = content
      .replace(/,\s*\]/g, ']')
      .replace(/,\s*\}/g, '}');
    output = JSON.parse(cleanedContent);
  } catch (secondaryError) {
    return [{
      json: {
        error: 'Failed to parse attributes',
        attributeData: null,
        products: [],
        summary: {}
      }
    }];
  }
}

// Summary statistics are computed in code from the data, not by the model.
const filtered = $('Remove Invalid Products').first().json.filteredProducts || [];
const priceOf = p => { const m = String(p && p.price != null ? p.price : '').replace(/,/g, '').match(/\d+(\.\d+)?/); return m ? parseFloat(m[0]) : null; };
const prices = filtered.map(priceOf).filter(v => v !== null).sort((a, b) => a - b);
const bucketOf = v => v < 50 ? 'Under $50' : v < 100 ? '$50-100' : v < 200 ? '$100-200' : v < 500 ? '$200-500' : '$500+';
const price_distribution = {};
prices.forEach(v => { const k = bucketOf(v); price_distribution[k] = (price_distribution[k] || 0) + 1; });
const mid = Math.floor(prices.length / 2);
const median = prices.length ? (prices.length % 2 ? prices[mid] : (prices[mid - 1] + prices[mid]) / 2) : null;
const attrTally = key => Object.entries((output.products || []).reduce((acc, p) => {
  const v = p && p.attributes ? p.attributes[key] : null;
  if (v) acc[v] = (acc[v] || 0) + 1;
  return acc;
}, {})).sort((a, b) => b[1] - a[1]).slice(0, 5).map(([name, count]) => ({ name, count }));
const summary = {
  product_count: prices.length,
  price_min: prices.length ? prices[0] : null,
  price_median: median,
  price_mean: prices.length ? +(prices.reduce((a, b) => a + b, 0) / prices.length).toFixed(2) : null,
  price_max: prices.length ? prices[prices.length - 1] : null,
  price_distribution,
  top_sizes: attrTally('size'), top_colors: attrTally('color'), top_materials: attrTally('material'),
  top_patterns: attrTally('pattern'), top_styles: attrTally('style')
};
output.summary = summary;

// Return matching your exact layout with standard native n8n array formatting
return [{
  json: {
    attributeData: output,
    products: output.products || [],
    summary: summary
  }
}];

// Access the inner choices element array safely without using deep empty chain symbols
let content = "";

if (typeof $json.choices !== 'undefined' && $json.choices !== null) {
  if (Array.isArray($json.choices) && $json.choices.length > 0) {
    if ($json.choices[0].message && $json.choices[0].message.content) {
      content = $json.choices[0].message.content;
    }
  } else if ($json.choices.message && $json.choices.message.content) {
    content = $json.choices.message.content;
  }
}

if (!content) {
  throw new Error("The preceding Identify Top Trends node did not return a valid content response text block.");
}

// Strip out any markdown wraps if the model natively outputs them
content = content.replace(/^```json\s*/i, '').replace(/```\s*$/, '').trim();

// Self-heal: Drop any conversational trailing apologies or non-JSON text
if (content.includes('}') && !content.endsWith('}') && !content.endsWith(']')) {
  const lastBraceIndex = content.lastIndexOf('}');
  if (lastBraceIndex !== -1) {
    content = content.substring(0, lastBraceIndex + 1);
  }
}

let output;
try {
  output = JSON.parse(content);
} catch (parseError) {
  try {
    // Clean minor syntax slips like trailing array commas
    let cleanedContent = content
      .replace(/,\s*\]/g, ']')
      .replace(/,\s*\}/g, '}');
    output = JSON.parse(cleanedContent);
  } catch (secondaryError) {
    // Fallback default segments structure if parsing is entirely corrupted
    output = {
      micro_segments: [
        {
          name: 'Classic Neutral',
          description: 'Timeless neutral tones with subtle patterns',
          visual_characteristics: ['neutral colors', 'subtle patterns', 'versatile design'],
          color_palette: ['Cream', 'Gray', 'Beige'],
          typical_materials: ['Polyester', 'Polypropylene'],
          target_rooms: ['living room', 'bedroom'],
          price_positioning: 'mid-range',
          trend_signals: ['Based on product data analysis'],
          image_prompt_keywords: ['neutral rug', 'modern interior', 'cozy living room']
        }
      ]
    };
  }
}

// Ensure micro_segments array is safely extracted
const segments = output.micro_segments || [];

return [{
  json: {
    microSegments: segments,
    segmentCount: segments.length
  }
}];

// Split micro-segments for individual image generation
const segments = $input.first().json.microSegments || [];

if (segments.length === 0) {
  return [{ json: { segment: null, skip: true } }];
}

return segments.map(segment => ({ json: { segment } }));

