const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  let base64 = '';

  try {
    // Safely pull the real binary buffer regardless of n8n's storage pointer backend
    const binaryBuffer = await this.helpers.getBinaryDataBuffer(i, 'data');
    base64 = binaryBuffer.toString('base64');
  } catch (e) {
    base64 = '';
  }

  // Recover the segment name from the Clean Prompt node (matched by position)
  let segmentName = 'Style';
  try {
    const src = $('Clean Prompt').all()[i];
    if (src && src.json.segmentName) segmentName = src.json.segmentName;
  } catch (e) { 
    // keep the fallback 
  }

  if (base64) {
    results.push({
      json: {
        segmentName: segmentName,
        base64Image: base64,
        mimeType: 'image/png',
        hasImage: true
      }
    });
  } else {
    results.push({
      json: {
        segmentName: segmentName,
        base64Image: null,
        mimeType: null,
        hasImage: false,
        error: 'Binary buffer processing failed'
      }
    });
  }
}

return results;

// Collect all generated images
const allImages = $input.all().map(item => ({
  segmentName: item.json.segmentName,
  base64Image: item.json.base64Image,
  mimeType: item.json.mimeType || 'image/png',
