  //                projected: { value: 0, unit: 'Billion', year: 2033 }, cagr_stated: null,
  //                source: 'Name of source', source_url: 'https://...' }
};

const cat = $('Get Category Key').first().json;
const catKey = cat.categoryKey || 'area_rug';

let resp = {};
try { resp = $('Fetch Market Data').first().json || {}; } catch (e) { resp = {}; }
const items = Array.isArray(resp.items) ? resp.items : [];

// Pick the market document: id first, then a title like "... Market Report / Analysis / Forecast"
const marketItem =
  items.find(i => /market/i.test(String(i.id || ''))) ||
  items.find(i => /market\s+(report|analysis|forecast|research)/i.test(String(i.title || ''))) ||
  null;

const rawContent = marketItem
  ? (typeof marketItem.content === 'string' ? marketItem.content : JSON.stringify(marketItem.content || ''))
  : '';

// The API text comes from a PDF: words are split ("Mark et", "CA GR"). Match on whitespace-free text.
const text = rawContent.replace(/\\n/g, '\n');
const compact = text.replace(/\s+/g, '');

const notes = [];
const num = s => { const v = parseFloat(String(s).replace(/,/g, '')); return Number.isFinite(v) ? v : null; };

let size = null, projected = null, cagrStated = null, cagrPeriod = null, us = null;

let m = compact.match(/Total(?:Global)?MarketSize(\d{4})(?:USD|\$)([\d.,]+)(Billion|Million|Trillion)/i)
     || compact.match(/MarketSize(\d{4})(?:USD|\$)([\d.,]+)(Billion|Million|Trillion)/i);
if (m) size = { value: num(m[2]), unit: m[3], year: parseInt(m[1], 10) };

m = compact.match(/Projected(?:Market)?Size(\d{4})(?:USD|\$)([\d.,]+)(Billion|Million|Trillion)/i);
if (m) projected = { value: num(m[2]), unit: m[3], year: parseInt(m[1], 10) };

m = compact.match(/CAGR\((\d{4})[-–]+(\d{4})\)([\d.]+)%/i);
if (m) { cagrStated = num(m[3]); cagrPeriod = `${m[1]}-${m[2]}`; }

m = compact.match(/U\.?S\.?Market:?(?:USD|\$)([\d.,]+)(Billion|Million)\((\d{4})\)[→>-]+(?:USD|\$)([\d.,]+)(Billion|Million)\((\d{4})\)/i);
if (m) us = { size: { value: num(m[1]), unit: m[2], year: parseInt(m[3], 10) },
              projected: { value: num(m[4]), unit: m[5], year: parseInt(m[6], 10) } };

// Scope: say exactly what the figures cover
let scope = 'As reported in the source document (scope not stated)';
if (/GlobalCarpet&RugMarket/i.test(compact)) scope = 'Global carpet & rug market (parent category, not the segment itself)';

// Optional named statistics. Add patterns here as your source documents allow.
const STATS = [
  { label: 'Medium price tier, market share',          re: /Medium([\d.]+)%Balance/i },
  { label: 'Premium price tier, growth (CAGR)',        re: /PremiumGrowingat([\d.]+)%CAGR/i },
  { label: 'Online retail, growth (CAGR)',             re: /OnlineRetailGrowingat([\d.]+)%CAGR/i },
  { label: 'Supermarkets/hypermarkets, market share',  re: /Supermarkets\/Hypermarkets([\d.]+)%/i },
  { label: 'Polyester, growth (CAGR)',                 re: /Polyester(?:Soft,fade-resistant,)?growingat([\d.]+)%CAGR/i },
  { label: 'Commercial outdoor spaces, growth (CAGR)', re: /CommercialOutdoorSpaces-?Hospitalitygrowthat([\d.]+)%CAGR/i },
  { label: 'Asia-Pacific, share of global consumption',re: /Asia-?PacificMarketShare:?([\d.]+)%/i },
  { label: 'Middle East & Africa, growth (CAGR)',      re: /MiddleEast&AfricaCAGR:?([\d.]+)%/i },
  { label: 'Eco-friendly, share of new product launches', re: /~?([\d.]+)%ofnewproductlaunchesfeatureeco-friendly/i }
];
const stats = STATS.map(s => { const x = compact.match(s.re); return x ? { label: s.label, value: num(x[1]) } : null; }).filter(Boolean);

// Manual fallback only when nothing usable was parsed
if (!size && !projected && cagrStated === null && FALLBACK[catKey]) {
  const f = FALLBACK[catKey];
  size = f.size || null; projected = f.projected || null; cagrStated = f.cagr_stated ?? null;
  scope = f.scope || scope;
  notes.push('Figures come from the manual fallback table, not the API.');
}

// CAGR computed from the two size figures: (end / start)^(1 / years) - 1
let cagrComputed = null;
if (size && projected && size.value > 0 && projected.value > 0 && projected.year > size.year && size.unit === projected.unit) {
  cagrComputed = (Math.pow(projected.value / size.value, 1 / (projected.year - size.year)) - 1) * 100;
}
const cagr = cagrStated !== null ? cagrStated : cagrComputed;
if (cagrStated === null && cagrComputed !== null) notes.push('CAGR computed from the two size figures.');
if (cagrStated !== null && cagrComputed !== null && Math.abs(cagrStated - cagrComputed) > 1)
  notes.push(`Published CAGR (${cagrStated}%) differs from the ${cagrComputed.toFixed(2)}% implied by the size figures.`);

if (!marketItem) notes.push('No market document was returned by the API for this category.');
else if (!size && !projected && cagr === null) notes.push('A market document was found but no size, projection or CAGR could be read from it.');

const fmtMoney = o => (o && o.value !== null) ? `USD ${o.value.toFixed(2)} ${o.unit.toLowerCase()}` : 'Not available';
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const card = (label, value, sub) =>
  `<div class="profile-card"><h4>${esc(label)}</h4><p style="font-size: 24px; font-weight: bold; color: #059669;">${esc(value)}</p>${sub ? `<small>${esc(sub)}</small>` : ''}</div>`;

const cagrSub = cagrStated !== null ? `As published${cagrPeriod ? `, ${cagrPeriod}` : ''}` : (cagrComputed !== null ? 'Computed from size figures' : '');
const srcName = marketItem ? (marketItem.source_name || '') : '';
const srcUrl = marketItem ? (marketItem.url || '') : '';
const pub = marketItem ? (marketItem.published_at || '') : '';
const sourceLine = marketItem
  ? `Source: ${srcUrl ? `<a href="${esc(srcUrl)}">${esc(srcName || srcUrl)}</a>` : esc(srcName)}${pub ? `, published ${esc(pub)}` : ''}. Underlying vendor estimates; treat as indicative.`
  : 'No source document available.';

let factsHtml = `<div class="market-data"><h3>Market Data & Forecasts</h3>` +
  `<p><small>Scope: ${esc(scope)}</small></p><div class="profile-grid">` +
  card(`Market Size${size ? ` (${size.year})` : ''}`, fmtMoney(size), '') +
  card(`Projected${projected ? ` (${projected.year})` : ''}`, fmtMoney(projected), '') +
  card('CAGR', cagr === null ? 'Not available' : `${cagr.toFixed(2)}%`, cagrSub) +
  `</div>`;
if (us) {
  factsHtml += `<div class="profile-grid">` +
    card(`U.S. Market (${us.size.year})`, fmtMoney(us.size), '') +
    card(`U.S. Projected (${us.projected.year})`, fmtMoney(us.projected), '') +
    `</div>`;
}
if (stats.length) {
  factsHtml += `<h4>Reported Segment Statistics</h4><table style="width:100%; border-collapse: collapse; font-size: 0.95em;">` +
    stats.map(s => `<tr><td style="padding:6px 8px; border-bottom:1px solid #eee;">${esc(s.label)}</td><td style="padding:6px 8px; border-bottom:1px solid #eee; text-align:right;"><strong>${s.value}%</strong></td></tr>`).join('') +
    `</table>`;
}
factsHtml += `<p><small>${sourceLine}${notes.length ? ' ' + esc(notes.join(' ')) : ''}</small></p></div>`;

return [{
  json: {
    factsHtml,
    facts: {
      scope,
      market_size: size, projected_size: projected,
      cagr_percent: cagr === null ? null : +cagr.toFixed(2),
      cagr_period: cagrPeriod,
      us_market: us,
      reported_statistics: stats,
      source: srcName || null, source_url: srcUrl || null, published: pub || null
    },
    marketDocFound: !!marketItem,
    notes
  }
}];
